require('dotenv').config();

const BASE_URL = 'https://openrouter.ai/api/v1/chat/completions';

/**
 * Strips internal thinking/chain-of-thought tags (e.g. <think>...</think>, <thought>...</thought>)
 * generated by reasoning models so internal monologues never leak to the user.
 */
function stripThinkingTags(text) {
  if (!text || typeof text !== 'string') return '';
  // Remove closed <think>...</think> or <thought>...</thought> blocks
  let cleaned = text.replace(/<(think|thought)>[\s\S]*?<\/\1>/gi, '').trim();
  // If there's an unclosed <think> or <thought> tag (model cut off mid-thought), remove it
  cleaned = cleaned.replace(/<(think|thought)>[\s\S]*$/gi, '').trim();
  return cleaned;
}

/**
 * Send a chat completion request to OpenRouter.
 * Returns the raw assistant message object (content + optional tool_calls)
 * so the caller can handle multi-turn tool-calling loops.
 */
async function chatCompletion({ messages, tools, maxTokens = 1500, temperature = 0.7 }) {
  const apiKey = process.env.OPENROUTER_API_KEY || process.env.API_KEY;
  const model = process.env.OPENROUTER_MODEL || 'openai/gpt-4o-mini';

  const body = {
    model,
    max_tokens: maxTokens,
    temperature,
    messages,
    reasoning: {
      effort: 'low',
      exclude: true,
    },
  };

  if (tools && tools.length > 0) {
    body.tools = tools;
    body.tool_choice = 'auto';
  }

  let choice; // will be set after successful request
  let data; // response payload
  const MAX_RETRIES = 3;
  const RETRY_DELAY_MS = 2000;
  let attempt = 0;
  let res;

  while (attempt < MAX_RETRIES) {
    try {
      res = await fetch(BASE_URL, {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${apiKey}`,
          'Content-Type': 'application/json',
          'HTTP-Referer': process.env.APP_URL || 'https://discord.com',
          'X-Title': 'Cutie Discord Bot',
        },
        body: JSON.stringify(body),
      });

      if (!res.ok) {
        const errText = await res.text();
        // If provider rejects reasoning parameter with 400 Bad Request, retry without it
        if (res.status === 400 && body.reasoning) {
          console.warn('OpenRouter 400 with reasoning parameter, retrying without reasoning object...');
          delete body.reasoning;
          continue;
        }
        // Retry on rate limit or overload status codes
        if (res.status === 429 || errText.toLowerCase().includes('overload')) {
          attempt++;
          console.warn(`OpenRouter request overload (status ${res.status}), retry ${attempt}/${MAX_RETRIES}`);
          await new Promise(r => setTimeout(r, RETRY_DELAY_MS * attempt));
          continue;
        }
        throw new Error(`OpenRouter error ${res.status}: ${errText}`);
      }

      data = await res.json();
      if (data.error) {
        // Retry without reasoning if error mentions reasoning
        if (body.reasoning && (data.error.code === 400 || (data.error.message && data.error.message.toLowerCase().includes('reasoning')))) {
          console.warn('OpenRouter payload error with reasoning, retrying without reasoning object...');
          delete body.reasoning;
          continue;
        }
        // Retry on overload errors reported in payload
        if (data.error.message && data.error.message.toLowerCase().includes('overload')) {
          attempt++;
          console.warn(`OpenRouter payload overload error, retry ${attempt}/${MAX_RETRIES}`);
          await new Promise(r => setTimeout(r, RETRY_DELAY_MS * attempt));
          continue;
        }
        throw new Error(`OpenRouter error: ${data.error.message || JSON.stringify(data.error)}`);
      }

      choice = data.choices?.[0];
      if (!choice) {
        throw new Error(`No response returned from OpenRouter. Full response: ${JSON.stringify(data)}`);
      }
      // Successful response, break loop
      break;
    } catch (err) {
      if (attempt >= MAX_RETRIES - 1) {
        throw err;
      }
      attempt++;
      console.warn(`OpenRouter request failed (${err.message}), retry ${attempt}/${MAX_RETRIES}`);
      await new Promise(r => setTimeout(r, RETRY_DELAY_MS * attempt));
    }
  }

  if (!choice) {
    throw new Error(`No response returned from OpenRouter. Full response: ${JSON.stringify(data)}`);
  }

  // Clean thinking/reasoning tags if present in content
  if (choice.message && typeof choice.message.content === 'string') {
    choice.message.content = stripThinkingTags(choice.message.content);
  }

  // NOTE: Strictly never assign choice.message.reasoning to content!
  // Reasoning tokens are internal chain-of-thought scratchpad data, not user-facing responses.

  // Ensure the response contains content or tool calls; throw error if empty so caller fallback is triggered
  if (!choice.message || (!choice.message.content && (!choice.message.tool_calls || choice.message.tool_calls.length === 0))) {
    throw new Error('OpenRouter response contains empty content and no tool calls.');
  }

  return choice.message; // { role: 'assistant', content, tool_calls? }
}

module.exports = { chatCompletion, stripThinkingTags };
